<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const favoriteKey='ozman_real_estate_favorites',propertyId={{ $property->id }},fav=document.getElementById('favorite');function favoriteIds(){try{return JSON.parse(localStorage.getItem(favoriteKey)||'[]').map(Number)}catch(e){return[]}}function paintFavorite(){const on=favoriteIds().includes(propertyId);fav.textContent=(on?'♥ ':'♡ ')+'{{ $labels['favorite'] }}';fav.style.color=on?'#ff718c':''}fav.onclick=()=>{let ids=favoriteIds();ids=ids.includes(propertyId)?ids.filter(i=>i!==propertyId):[...ids,propertyId];localStorage.setItem(favoriteKey,JSON.stringify(ids));paintFavorite()};paintFavorite();document.getElementById('share').onclick=async()=>{const data={title:@json($title),text:@json($description),url:location.href};if(navigator.share)await navigator.share(data);else{await navigator.clipboard.writeText(location.href);alert('تم نسخ الرابط')}};@if($property->purpose==='sale')function calculate(){const price={{ (float)$property->price }},down=Number(document.getElementById('down').value||0),years=Number(document.getElementById('years').value||1),annual=Number(document.getElementById('interest').value||0)/100,principal=Math.max(0,price-down),months=years*12,rate=annual/12;const payment=rate?principal*rate*Math.pow(1+rate,months)/(Math.pow(1+rate,months)-1):principal/months;document.getElementById('calculation').textContent='{{ $labels['monthly'] }}: '+Math.round(payment).toLocaleString()+' {{ $property->currency }}'}document.querySelectorAll('.calculator input').forEach(i=>i.oninput=calculate);calculate();@endif @if($property->latitude&&$property->longitude)if(window.L){const map=L.map('property-map').setView([{{ $property->latitude }},{{ $property->longitude }}],15);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);L.marker([{{ $property->latitude }},{{ $property->longitude }}]).addTo(map).bindPopup(@json($title)).openPopup()}@endif</script></body></html>
